import{_ as e,o as n,c as o,ag as s}from"./chunks/framework.BZohXCq9.js";const g=JSON.parse('{"title":"Commission and Stripe: Where It’s Configured and How to Verify","description":"","frontmatter":{},"headers":[],"relativePath":"COMMISSION_AND_STRIPE_GUIDE.md","filePath":"COMMISSION_AND_STRIPE_GUIDE.md"}'),r={name:"COMMISSION_AND_STRIPE_GUIDE.md"};function a(i,t,m,h,c,d){return n(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="commission-and-stripe-where-it-s-configured-and-how-to-verify" tabindex="-1">Commission and Stripe: Where It’s Configured and How to Verify <a class="header-anchor" href="#commission-and-stripe-where-it-s-configured-and-how-to-verify" aria-label="Permalink to &quot;Commission and Stripe: Where It’s Configured and How to Verify&quot;">​</a></h1><p>This document explains where DSP commission is configured, how to see commission data in the DSP dashboard, and what appears (and what does not) in the Stripe test environment. It is written for the client and for anyone validating the payment system.</p><hr><h2 id="_1-where-commission-is-configured" tabindex="-1">1. Where commission is configured <a class="header-anchor" href="#_1-where-commission-is-configured" aria-label="Permalink to &quot;1. Where commission is configured&quot;">​</a></h2><p><strong>Commission is configured only in the DSP platform, not in Stripe.</strong></p><ul><li><strong>Location:</strong> <strong>DSP Admin Dashboard → Payment Management → Commission Management</strong> (tab within the Payment Management page).</li><li><strong>What you can set:</strong><ul><li><strong>Commission type:</strong> Percentage or fixed amount.</li><li><strong>Commission value:</strong> For percentage, the platform’s share (e.g. 40 means the admin gets 40%, the instructor gets 60%). For fixed amount, the platform’s share per lesson in CHF.</li><li><strong>Default instructor share (%):</strong> The percentage the instructor gets by default (e.g. 80 = instructor 80%, admin 20%). This is the <strong>platform-wide default</strong> applied to every instructor who does <strong>not</strong> have a custom commission set.</li></ul></li></ul><p><strong>Per-instructor override</strong></p><ul><li><strong>Location:</strong> <strong>DSP Admin Dashboard → Instructor Management</strong> → open an instructor (detail modal).</li><li><strong>Commission override</strong> section: You can set an <strong>Instructor share (%)</strong> for that instructor only (e.g. 60% → instructor gets 60%, admin gets 40%). If you leave it empty or click <strong>“Use platform default”</strong>, that instructor uses the <strong>Default instructor share (%)</strong> from Commission Management instead.</li></ul><p>So: if an instructor has a custom commission set, that value is used; otherwise the platform default (Default instructor share or the legacy commission value) applies. The same logic is used for instant payments at checkout, deferred (T-48) charges, and payouts. Commission is <strong>not</strong> configurable per transaction in the Stripe Dashboard; Stripe only sees the full payment and the transfer we send to the instructor’s Connect account.</p><hr><h2 id="_2-how-to-verify-commission-in-the-dsp-dashboard" tabindex="-1">2. How to verify commission in the DSP dashboard <a class="header-anchor" href="#_2-how-to-verify-commission-in-the-dsp-dashboard" aria-label="Permalink to &quot;2. How to verify commission in the DSP dashboard&quot;">​</a></h2><h3 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;Admin&quot;">​</a></h3><ul><li><strong>Payment Management → Transactions</strong><ul><li>Use the <strong>party</strong> tabs (Admin / Instructor / Student) and the <strong>type</strong> tabs (Payments, Refunds, Payouts, etc.) to filter.</li><li><strong>Admin / Platform view:</strong> Look for transactions with description like <strong>“Platform commission for booked slot”</strong> or <strong>“Platform gross receipt …”</strong>. The former is the commission (platform’s share); the latter is the full amount received before the split.</li><li><strong>Commission Management</strong> tab (same page): Shows the current default rate/type and value. Changing them and saving updates the commission applied to <strong>new</strong> payments.</li></ul></li></ul><h3 id="instructor" tabindex="-1">Instructor <a class="header-anchor" href="#instructor" aria-label="Permalink to &quot;Instructor&quot;">​</a></h3><ul><li><strong>Instructor Dashboard → Transaction History</strong> (and Profile → Payment Management transaction list) <ul><li>Instructors see only their <strong>net</strong> earnings (their share after commission). Each “payment” line is the amount they receive per lesson/slot. Commission is not shown as a separate line for instructors; it is already deducted.</li></ul></li></ul><h3 id="student" tabindex="-1">Student <a class="header-anchor" href="#student" aria-label="Permalink to &quot;Student&quot;">​</a></h3><ul><li><strong>Student Dashboard → Payment History</strong><ul><li>Students see what they <strong>paid</strong> (the full lesson price in CHF). They do not see commission or instructor share.</li></ul></li></ul><hr><h2 id="_3-why-the-stripe-test-environment-doesn-t-show-commission" tabindex="-1">3. Why the Stripe test environment doesn’t show “commission” <a class="header-anchor" href="#_3-why-the-stripe-test-environment-doesn-t-show-commission" aria-label="Permalink to &quot;3. Why the Stripe test environment doesn’t show “commission”&quot;">​</a></h2><p>Stripe does not have a built-in concept of “platform commission” as a separate transaction type. Our flow is:</p><ol><li><strong>Student pays</strong> → Stripe records a <strong>Payment</strong> (full amount) on the <strong>platform</strong> account.</li><li><strong>We then transfer</strong> the instructor’s share to the instructor’s <strong>Stripe Connect</strong> (Express) account.</li><li><strong>What remains</strong> on the platform account is the commission. We do not send that to Stripe as a separate “commission” transaction; we simply keep it on the platform balance.</li></ol><p>So in Stripe you will see:</p><ul><li><strong>Payments</strong> – The full (gross) amount of each charge.</li><li><strong>Connect → Accounts → [Instructor] → Transfers</strong> – The amount we sent to each instructor (their net share).</li></ul><p>There is <strong>no</strong> Stripe section labeled “Commission”. The commission is the difference between what we received (Payments) and what we transferred (Transfers), and it is fully visible and manageable in the <strong>DSP Admin Dashboard</strong> (Payment Management → Transactions and Commission Management).</p><p><strong>In test mode:</strong> The same logic applies. Use test cards and the DSP admin transaction list and Commission Management to verify that changing the commission rate/type in the admin panel correctly affects new payments and that admin/instructor transaction amounts match the configured split.</p><hr><p>Truth / what to tell the client Stripe Dashboard will NOT show a separate “DSP commission” line item. Stripe records:</p><p>the full payment (gross) on the platform Stripe account, and (if you use Connect transfers) the transfer to the instructor’s connected account. The difference is effectively the platform’s commission, but Stripe does not label it as “commission” or show a dedicated “commission transaction”. Where they can actually verify commission is in the DSP Admin Dashboard, not Stripe:</p><p>Admin → Payment Management → Commission Management: shows the configured default commission (rate/type). Admin → Payment Management → Transactions: shows platform-side transactions (gross receipt and commission entries) so they can confirm amounts per booking/slot. Suggested client answer (copy/paste) In Stripe, you won’t see a separate “DSP commission” transaction. Stripe only shows the gross payment and (for Connect) the transfer to the instructor account. Stripe doesn’t label the retained amount as “commission”. To verify commission, please use the DSP Admin Dashboard → Payment Management:</p><p>Commission Management shows the configured commission rate/type. Transactions shows the platform’s gross receipts and commission amounts per lesson/slot.</p><h2 id="_4-summary-where-to-configure-and-verify" tabindex="-1">4. Summary: where to configure and verify <a class="header-anchor" href="#_4-summary-where-to-configure-and-verify" aria-label="Permalink to &quot;4. Summary: where to configure and verify&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you want to do</th><th>Where</th></tr></thead><tbody><tr><td><strong>Configure commission</strong> (rate, type, default instructor %)</td><td>DSP Admin Dashboard → Payment Management → <strong>Commission Management</strong> tab</td></tr><tr><td><strong>Set per-instructor commission override</strong></td><td>DSP Admin Dashboard → <strong>Instructor Management</strong> → open instructor → <strong>Commission override</strong></td></tr><tr><td><strong>See platform commission and gross receipts</strong></td><td>DSP Admin Dashboard → Payment Management → <strong>Transactions</strong> (filter by Admin/Platform and type)</td></tr><tr><td><strong>See instructor net earnings</strong></td><td>Instructor Dashboard → <strong>Transaction History</strong> (and Payment tab transaction list)</td></tr><tr><td><strong>See what the student paid</strong></td><td>Student Dashboard → <strong>Payment History</strong></td></tr><tr><td><strong>See gross payments in Stripe</strong></td><td>Stripe Dashboard → <strong>Payments</strong></td></tr><tr><td><strong>See what was sent to instructors</strong></td><td>Stripe Dashboard → <strong>Connect → Accounts</strong> → select instructor → <strong>Transfers</strong></td></tr><tr><td><strong>See “commission” in Stripe</strong></td><td>Not available; commission = (Payments − Transfers), managed in DSP Admin</td></tr></tbody></table><hr><h2 id="_5-quick-checklist-for-validating-commission" tabindex="-1">5. Quick checklist for validating commission <a class="header-anchor" href="#_5-quick-checklist-for-validating-commission" aria-label="Permalink to &quot;5. Quick checklist for validating commission&quot;">​</a></h2><ol><li>Set a known commission in <strong>Admin → Payment Management → Commission Management</strong> (e.g. 40%).</li><li>As a student, pay for a lesson (test card, e.g. 4242 4242 4242 4242).</li><li>In <strong>Admin → Payment Management → Transactions</strong>, confirm: <ul><li>A “Platform gross receipt” (or similar) for the full amount.</li><li>A “Platform commission” (or similar) for the platform’s share (e.g. 40% of the amount).</li></ul></li><li>In <strong>Instructor Dashboard → Transaction History</strong>, confirm the instructor sees only their net share (e.g. 60% of the lesson price).</li><li>In <strong>Stripe Dashboard</strong>, confirm the Payment appears for the full amount and that a Transfer to the instructor’s Connect account matches the instructor’s net share.</li></ol><p>This confirms that commission is configured in the DSP admin panel, applied correctly in the app, and visible in the DSP dashboards; Stripe shows payments and transfers, and the difference is the commission we keep on the platform.</p>',36)])])}const u=e(r,[["render",a]]);export{g as __pageData,u as default};
